// Changes: Tests of the shared table model (LL table, Empty/First/Follow, Predict, precedence table).

import { describe, expect, it } from 'vitest'
import { analyzeGrammar } from './analysis'
import { setRelation, setTerminals } from './precedence'
import { defaultProjectData } from './project'
import { llPredictTableModel, llSetsTableModel, llTableModel, precTableModel, tableGrid } from './tableModel'

const ll = (rules: string) => analyzeGrammar({ rules, nonterminals: '', terminals: '', start: '' }).ll!

describe('llTableModel', () => {
  it('has a row per nonterminal, a column per terminal with $ last, and rule numbers in the cells', () => {
    const m = llTableModel(ll('S -> a S | ε'))
    expect(m.title).toBe('LL tabuľka')
    expect(tableGrid(m)).toEqual([
      ['', 'a', '$'],
      ['S', '1', '2'],
    ])
  })

  it('marks conflicts explicitly and explains every cell with its rules', () => {
    const m = llTableModel(ll('S -> a | a b'))
    const cell = m.rows[0].cells[0]
    expect(cell).toEqual({ text: '1, 2', conflict: true, title: '1: S → a\n2: S → a b' })
    expect(m.rows[0].cells[2]).toEqual({ text: '', conflict: false, title: '' })
  })

  it('does not treat a terminal with a comma as a conflict', () => {
    const m = llTableModel(ll("S -> ',' S | ε"))
    expect(m.header).toEqual(['', ',', '$'])
    expect(m.rows[0].cells.map((c) => c.conflict)).toEqual([false, false])
  })
})

describe('Empty/First/Follow and Predict models', () => {
  const a = ll("E -> T E'\nE' -> + T E' | ε\nT -> i")

  it('lists Empty, First and Follow per nonterminal', () => {
    expect(tableGrid(llSetsTableModel(a))).toEqual([
      ['Neterminál', 'Empty', 'First', 'Follow'],
      ['E', '∅', '{ i }', '{ $ }'],
      ["E'", '{ ε }', '{ + }', '{ $ }'],
      ['T', '∅', '{ i }', '{ +, $ }'],
    ])
  })

  it('lists Predict per numbered rule', () => {
    expect(tableGrid(llPredictTableModel(a))).toEqual([
      ['#', 'Pravidlo', 'Predict'],
      ['1', "E → T E'", '{ i }'],
      ['2', "E' → + T E'", '{ + }'],
      ['3', "E' → ε", '{ $ }'],
      ['4', 'T → i', '{ i }'],
    ])
  })
})

describe('precTableModel', () => {
  it('shows the relations with $ last and describes each cell', () => {
    let prec = setTerminals(defaultProjectData().prec, ['i'])
    prec = setRelation(prec, '$', 'i', '<')
    const m = precTableModel(prec)
    expect(m.title).toBe('Precedenčná tabuľka')
    expect(tableGrid(m)).toEqual([
      ['', 'i', '$'],
      ['i', '', ''],
      ['$', '<', ''],
    ])
    expect(m.rows[1].cells[0]).toEqual({ text: '<', conflict: false, title: 'Tabuľka[$, i] = <' })
    expect(m.rows[1].cells[1].title).toBe('Tabuľka[$, $] = prázdne (chyba)')
  })
})
